const TRAVANCORE_FROG_INFO={id:"travancore-flying-frog",commonName:"Travancore Flying Frog",scientificName:"Rhacophorus travancoricus",family:"Rhacophoridae",genus:"Rhacophorus",species:"R. travancoricus",endemicRegion:"Southern Western Ghats (Kerala & Tamil Nadu)",iucnStatus:"Endangered (IUCN 3.1)",protectionStatus:"Schedule II (Indian Wildlife Protection Act, 1972)",habitatType:"Tropical evergreen rainforest canopy, bamboo thickets, and mountain streams",avgSize:"55 to 65 mm (Females larger than males)",lifespan:"5 to 8 years in natural rainforest canopy",dietType:"Insectivorous (Moths, flies, crickets, beetles, ants)",quickStats:[{label:"Endemic Range",value:"Southern Western Ghats",icon:"🍃"},{label:"IUCN Red List",value:"Endangered",icon:"🛡️"},{label:"Gliding Adaptation",value:"Full Interdigital Webbing",icon:"🪂"},{label:"Nesting Style",value:"Suspended Foam Nest",icon:"🫧"},{label:"Avg Body Length",value:"55–65 mm",icon:"🐸"},{label:"Primary Zone",value:"Rainforest Canopy",icon:"🌳"}]},TAXONOMY_DATA={kingdom:"Animalia",phylum:"Chordata",class:"Amphibia",order:"Anura",family:"Rhacophoridae",genus:"Rhacophorus",species:"Rhacophorus travancoricus (Boulenger, 1891)"},ECOLOGY_BEHAVIOUR={introduction:"The Travancore Flying Frog (Rhacophorus travancoricus) is an extraordinary, small arboreal amphibian endemic to the wet evergreen rainforests of the southern Western Ghats.",distribution:"Restricted to high-elevation rainforest tracts across Kerala and Tamil Nadu, including Agasthyamalai Biosphere Reserve, Periyar Tiger Reserve, and Anamalai Hills.",habitat:"Occupy upper canopy strata (8 to 20 meters high) of tropical evergreen forests, dense reed bamboo brake, and vegetation surrounding temporary forest pools.",morphology:"Features vibrant grass-green dorsal skin with subtle reddish-brown spots, bright reddish-orange webbing between digits, enlarged adhesive toe discs, and skin flaps on heel margins.",behaviour:"Arboreal parachutist. Spreads fully webbed hands and feet when leaping from high tree branches, gliding up to 10–12 meters downward to lower leaves.",diet:"Nocturnal ambush hunter feeding on airborne insects, moths, tree crickets, beetles, and small flies.",reproduction:"Mating pairs construct suspended foam nests on overhanging leaves above ephemeral rainwater pools. Eggs hatch into tadpoles that drop into the water below.",conservation:"Listed as Endangered by the IUCN due to severe habitat fragmentation caused by timber logging, tea plantations, and climate-induced drought."},INTERESTING_FACTS=[{title:"Parachuting Aerodynamics",description:"Expands its webbed hands and feet into broad aerodynamic parachutes to slow fall speed and control descent trajectory."},{title:"Foam Nest Architecture",description:"Couples whip secretional fluids into a protective foam nest that hardens on the outside to prevent egg desiccation."},{title:"Camouflage Master",description:"Blends seamlessly into wet tropical foliage, making it almost invisible to predatory pit vipers and birds."},{title:"Boulenger Discovery (1891)",description:"First described by renowned Belgian-British zoologist George Albert Boulenger from specimens collected in Travancore."}],GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Rhacophorus_travancoricus.jpg/800px-Rhacophorus_travancoricus.jpg",caption:"Travancore Flying Frog (Rhacophorus travancoricus) perched on wet rainforest leaf",category:"Morphology"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Western_Ghats_Kerala_Rainforest.jpg/800px-Western_Ghats_Kerala_Rainforest.jpg",caption:"Agasthyamalai Rainforest — Native habitat of the Travancore Flying Frog",category:"Habitat"}],REFERENCES=[{text:"Boulenger, G. A. (1891). Description of a new frog from Travancore. Annals and Magazine of Natural History.",link:"#"},{text:"IUCN Red List of Threatened Species — Rhacophorus travancoricus assessment.",link:"https://www.iucnredlist.org"},{text:"Biju, S. D., & Bossuyt, F. (2009). Systematics and conservation of Western Ghats Rhacophoridae.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={TRAVANCORE_FROG_INFO:TRAVANCORE_FROG_INFO,TAXONOMY_DATA:TAXONOMY_DATA,ECOLOGY_BEHAVIOUR:ECOLOGY_BEHAVIOUR,INTERESTING_FACTS:INTERESTING_FACTS,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});